import tarfile
import os

def solve(primary: str, comparison: str):
    def get_final_components_from_tar(tar_path, is_dir):
        try:
            with tarfile.open(tar_path, 'r') as tar:
                members = tar.getmembers()
                components = set()
                for member in members:
                    if (member.isfile() and not is_dir) or (member.isdir() and is_dir):
                        name = member.name.rstrip('/')
                        if name:
                            components.add(os.path.basename(name))
                return components
        except Exception as e:
            raise RuntimeError(f"Failed to read tar archive {tar_path}: {e}")

    primary_set = get_final_components_from_tar(primary, False)
    comparison_set = get_final_components_from_tar(comparison, True)

    result = sorted(primary_set - comparison_set)
    return result
